  <script>
    class CoinRenderer {
      constructor(canvas) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.width = canvas.offsetWidth;
        this.height = canvas.offsetHeight;
        this.dpr = window.devicePixelRatio || 1;

        canvas.width = this.width * this.dpr;
        canvas.height = this.height * this.dpr;
        this.ctx.scale(this.dpr, this.dpr);

        this.time = 0;
        this.isPlaying = true;
        this.animate();
      }

      render(t) {
        const ctx = this.ctx;
        const w = this.width;
        const h = this.height;
        const cx = w / 2;
        const cy = h / 2;

        ctx.fillStyle = '#0a0e27';
        ctx.fillRect(0, 0, w, h);

        const rotY = t * Math.PI * 2;
        const rotX = Math.sin(t * Math.PI * 2) * Math.PI * 0.35;

        ctx.save();
        ctx.translate(cx, cy);

        this.drawCoin(rotY, rotX);

        ctx.restore();
      }

      drawCoin(rotY, rotX) {
        const ctx = this.ctx;
        const radius = Math.min(this.width, this.height) * 0.35;
        const thickness = radius * 0.15;

        const cosX = Math.cos(rotX);
        const sinX = Math.sin(rotX);
        const cosY = Math.cos(rotY);
        const sinY = Math.sin(rotY);

        const points = [];
        const segments = 96;

        for (let i = 0; i < segments; i++) {
          const angle = (i / segments) * Math.PI * 2;
          const cos = Math.cos(angle);
          const sin = Math.sin(angle);

          for (let layer = -1; layer <= 1; layer += 2) {
            const z = thickness * layer;
            const x = cos * radius;
            const y = z;
            const rz = sin * radius;

            const x2 = x * cosY - rz * sinY;
            const z2 = x * sinY + rz * cosY;
            const y2 = y * cosX - z2 * sinX;
            const z3 = y * sinX + z2 * cosX;

            points.push({
              x: x2,
              y: y2,
              z: z3,
              angle: angle,
              layer: layer,
              idx: i
            });
          }
        }

        points.sort((a, b) => a.z - b.z);

        const metalColor = (r, g, b, intensity) => {
          const base = Math.max(r, g, b);
          const light = base + (1 - base) * intensity;
          return `rgb(${Math.floor(r * light * 255)}, ${Math.floor(g * light * 255)}, ${Math.floor(b * light * 255)})`;
        };

        const drawFace = (layer, metalR, metalG, metalB, label, isBack) => {
          ctx.fillStyle = metalColor(metalR, metalG, metalB, 0.6);
          ctx.beginPath();
          ctx.ellipse(0, 0, radius, radius * Math.cos(Math.PI / 6), 0, 0, Math.PI * 2);
          ctx.fill();

          const specX = Math.cos(layer * Math.PI * 4) * radius * 0.4;
          const specY = -radius * 0.3;
          const specW = radius * 0.25;
          const specH = radius * 0.15;

          ctx.fillStyle = `rgba(255, 255, 255, ${Math.max(0, Math.cos(layer * Math.PI * 4) * 0.7)})`;
          ctx.beginPath();
          ctx.ellipse(specX, specY, specW, specH, Math.PI / 4, 0, Math.PI * 2);
          ctx.fill();

          ctx.fillStyle = '#fbbf24';
          ctx.font = `${radius * 0.25}px sans-serif`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';

          if (isBack) {
            ctx.fillText('10,000', 0, -radius * 0.15);
            ctx.font = `${radius * 0.15}px sans-serif`;
            ctx.fillText('TOKENS', 0, radius * 0.15);
          } else {
            ctx.fillText('WT', 0, radius * 0.05);
          }
        };

        const frontVis = Math.cos(points[points.length - 1].angle) * 0.5 + 0.5;
        const backVis = 1 - frontVis;

        if (backVis > 0.1) {
          ctx.globalAlpha = backVis;
          drawFace(-1, 0.2, 0.2, 0.22, 'Back', true);
          ctx.globalAlpha = 1;
        }

        if (frontVis > 0.1) {
          ctx.globalAlpha = frontVis;
          drawFace(1, 0.85, 0.85, 0.88, 'Front', false);
          ctx.globalAlpha = 1;
        }

        ctx.strokeStyle = `rgba(200, 180, 140, ${0.4 * (0.5 + Math.cos(points[0].angle) * 0.5)})`;
        ctx.lineWidth = radius * 0.08;
        ctx.beginPath();
        ctx.ellipse(0, 0, radius, radius * Math.cos(Math.PI / 6) * 0.98, 0, 0, Math.PI * 2);
        ctx.stroke();

        for (let i = 0; i < segments; i += 3) {
          const angle = (i / segments) * Math.PI * 2;
          const cos = Math.cos(angle);
          const sin = Math.sin(angle);

          const x = cos * radius;
          const rz = sin * radius;
          const cosY = Math.cos(points[0].angle);
          const sinY = Math.sin(points[0].angle);
          const x2 = x * cosY - rz * sinY;

          const ridgeHeight = radius * 0.04;
          for (let r = 0; r < 1; r += 0.25) {
            const y = (r - 0.5) * thickness;
            const ridgeIntensity = Math.cos(r * Math.PI) * 0.5 + 0.5;
            ctx.fillStyle = metalColor(0.8, 0.8, 0.85, 0.3 * ridgeIntensity);
            ctx.beginPath();
            ctx.ellipse(x2, y, ridgeHeight * 0.5, ridgeHeight * 0.2, 0, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }

      animate() {
        if (this.isPlaying) {
          this.time = (this.time + 1 / 60 / 2) % 1;
        }
        this.render(this.time);
        requestAnimationFrame(() => this.animate());
      }

      pause() {
        this.isPlaying = false;
      }

      setTime(t) {
        this.time = Math.max(0, Math.min(1, t));
        this.render(this.time);
      }
    }

    const heroCanvas = document.getElementById('coin-hero');
    const heroRenderer = new CoinRenderer(heroCanvas);

    window.demo = {
      canvas: heroCanvas,
      setTime: (t) => heroRenderer.setTime(t),
      pause: () => heroRenderer.pause()
    };

    document.querySelectorAll('.edition-canvas').forEach((canvas, idx) => {
      const renderer = new CoinRenderer(canvas);
      renderer.time = (idx * 0.25) % 1;
    });
  </script>
